							k = len(arg)
						} else {
							if i+1 < len(args) {
								param = args[i+1]
								i++
							}
							k++
						}
						if param != "" {
							if _, err := strconv.Atoi(param); err != nil {
								unknownFlag = true
							} else {
								// ignore threads
							}
						}
						break
					case 'b':
						// benchmark level
						param := ""
						if k+1 < len(arg) {
							param = arg[k+1:]
