						} else {
							if i+1 < len(args) {
								param = args[i+1]
								i++
							}
							k++
						}
						opts.benchmark = true
						if param != "" {
							if _, err := strconv.Atoi(param); err != nil {
								unknownFlag = true
							}
						}
						break
					case 'e':
						param := ""
						if k+1 < len(arg) {
							param = arg[k+1:]
							k = len(arg)
						} else {
							if i+1 < len(args) {
								param = args[i+1]
								i++
							}
							k++
						}
						if param != "" {
							if _, err := strconv.Atoi(param); err != nil {
								unknownFlag = true
							}
						}
						break
					case 'i':
						param := ""
						if k+1 < len(arg) {
							param = arg[k+1:]
