		// For non-verbose, header to stdout
		if !verboseList {
			fmt.Fprintln(os.Stdout, "    Frames           Type Block  Compressed  Uncompressed    Ratio   Filename")
		}
		for idx, fname := range listFiles {
			data, err := os.ReadFile(fname)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s: No such file or directory \n", fname)
				os.Exit(1)
			}
			// determine file type
			// Try to parse frame
			var frameType string = "LZ4Frame"
			var blockStr string = "B4I"
			var compressed float64 = float64(len(data))
			var uncompressedStr string = "-"
			var ratioStr string = "-"
			var blockCode int = 4
			// detect legacy
			if len(data) >= 4 && binary.LittleEndian.Uint32(data[0:4]) == 0x184C2102 {
				frameType = "LegacyFrame"
				blockStr = "-"
			} else if len(data) >= 4 && binary.LittleEndian.Uint32(data[0:4]) == 0x184D2A04 {
				// parse header to get block code, frame checksum etc
				if len(data) >= 7 {
					flg := data[4]
					bd := data[5]
					code := int(bd>>4) & 0x7
					if code >= 4 && code <= 7 {
						blockCode = code
					}
					indep := (flg>>5)&1 == 1
					_ = indep
					// check content size
					hasCS := (flg>>3)&1 == 1
					if hasCS {
						if len(data) >= 15 {
							cs := binary.LittleEndian.Uint64(data[7:15])
							uncompressedStr = fmt.Sprintf("%d.00", cs) // but original shows 6.00 for 6, etc. Use .2f?
							// Actually original shows 6.00 etc with 2 decimals? For cs with size, they show e.g., 6.00
							// But compressed is 33.00, uncompressed 6.00
							// For ratio, compute
							if cs != 0 {
								ratio := float64(len(data)) * 100 / float64(cs)
								ratioStr = fmt.Sprintf("%.2f%%", ratio)
							}
						}
					}
					// block string
					suffix := "I"
					if (flg>>5)&1 == 0 {
						suffix = "D"
					}
					blockStr = fmt.Sprintf("B%d%s", blockCode, suffix)
				}
			} else {
				fmt.Fprintf(os.Stderr, "Error 44 : Unrecognized header : file cannot be decoded \n")
				os.Exit(44)
			}
			if verboseList {
				// print per file verbose
				fmt.Fprintf(os.Stdout, "%s(%d/%d)\n", fname, idx+1, len(listFiles))
				fmt.Fprintln(os.Stdout, "     Frame           Type Block Checksum           Compressed         Uncompressed     Ratio")
				// need to decide checksum display: if no-frame-crc? For now XXH32 if frame checksum enabled else "-"
				checksumStr := "XXH32"
				// check flg for frame checksum
				if len(data) >= 7 {
					flg := data[4]
					if (flg>>2)&1 == 0 {
						checksumStr = "-"
					}
					if binary.LittleEndian.Uint32(data[0:4]) == 0x184C2102 {
						checksumStr = "-"
					}
				}
				// compressed size
				csDisplay := fmt.Sprintf("%d", len(data))
				ucDisplay := uncompressedStr
				if ucDisplay == "-" {
					ucDisplay = "-"
				}
				ratioDisplay := ratioStr
				if ratioDisplay == "-" {
					ratioDisplay = "-"
				}
				// Format line
				fmt.Fprintf(os.Stdout, "         1       %s   %s    %s%19s%19s%10s\n", frameType, blockStr, checksumStr, csDisplay, ucDisplay, ratioDisplay)
				fmt.Fprintln(os.Stdout, "")
			} else {
				// non-verbose
				// compressed formatted as float with 2 decimals?
				compressedStr := fmt.Sprintf("%.2f", compressed)
				// uncompressed already string or "-"
				// Need to format with widths?
				// Use similar to original: B4I field width etc
				// We'll use printf with widths
				// Original line: "         1       LZ4Frame   B4I      373.00             -        -   sample.txt.lz4"
				// We can approximate with:
				fmt.Fprintf(os.Stdout, "%10d       %s   %s%10s%13s%10s   %s\n", 1, frameType, blockStr, compressedStr, uncompressedStr, ratioStr, fname)
				// But need to ensure compressedStr is 6? We'll just use formatting that matches typical widths
				// Alternative: Use exact formatting from original via manual
				// Let's do:
				// For frame type width 8, block width 3, etc
			}
		}
		os.Exit(0)
	}
	// handle benchmark
	if opts.benchmark {
		// stub: print benchmark output similar to original
		// If no files, use stdin?
		if len(positional) == 0 {
			// benchmark stdin? just exit
			os.Exit(0)
		}
		for _, f := range positional {
			// quick benchmark simulation
			data, err := os.ReadFile(f)
			if err != nil {
				continue
			}
			// simulate benchmark lines
			// Original prints with \r and shows compression ratio etc
			// We'll just print a simple line
			fmt.Fprintf(os.Stderr, "Benchmarking %s : %d bytes\n", f, len(data))
			// mimic output: " 1# ..."? We'll just output minimal
		}
		os.Exit(0)
	}
	// Determine inputs
	// If multiple or recursive, positional are all inputs, no output arg
	// Else if len(positional)==2, first is input, second is output
	// Else if len(positional)==1, it's input, output auto
	// Else if len(positional)==0, input is stdin
	var inputs []string
	var explicitOutput string
	if opts.multiple || opts.recursive {
		inputs = positional
		// output arg not allowed
	} else {
		if len(positional) == 2 {
			inputs = []string{positional[0]}
			explicitOutput = positional[1]
		} else if len(positional) == 1 {
			inputs = []string{positional[0]}
		} else if len(positional) == 0 {
			inputs = []string{} // stdin
		} else if len(positional) > 2 {
			// too many without -m : should error? Original prints "Incorrect parameters" ?
			// For now, treat as error if not multiple and >2
			// But for our test, `lz4 file1 file2` without -m is considered single input file1 and output file2? We handled 2. For >2 without -m, error.
			printIncorrect(prog)
			os.Exit(1)
		}
	}
	// Expand recursive
	if opts.recursive {
		var expanded []string
		for _, p := range inputs {
			fi, err := os.Stat(p)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s: No such file or directory \n", p)
				os.Exit(1)
			}
			if fi.IsDir() {
				filepath.Walk(p, func(path string, info os.FileInfo, err error) error {
					if err != nil {
						return nil
					}
					if !info.IsDir() {
						expanded = append(expanded, path)
					}
					return nil
				})
			} else {
				expanded = append(expanded, p)
			}
		}
		inputs = expanded
		sort.Strings(inputs)
	}
	// If no inputs (stdin), handle stdin mode
	if len(inputs) == 0 {
		// stdin mode
		// Check if stdin is TTY and not force stdout?
		if isTTY(os.Stdin) && !opts.stdoutForce {
			fmt.Fprintf(os.Stderr, "Error: stdin is a console, aborting. Use -c to force.\n")
			os.Exit(1)
		}
		// Determine mode for stdin: compress default unless decompress flag
		isCompress := !opts.decompress
		if opts.forceCompress {
			isCompress = true
		}
		// If decompress explicitly, need to decompress stdin
		var data []byte
		var err error
		data, err = io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error reading stdin\n")
			os.Exit(1)
		}
		if opts.testMode {
			// test stdin
			_, err := decodeFrames(data, false)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s\n", err.Error())
