				if strings.Contains(err.Error(), "40") {
					os.Exit(40)
				} else if strings.Contains(err.Error(), "44") {
					os.Exit(44)
				} else {
					os.Exit(1)
				}
			}
			os.Exit(0)
		}
		if isCompress {
			// check content-size warning
			if opts.contentSize && len(inputs)==0 {
				fmt.Fprintf(os.Stderr, "warning : --content-size cannot determine size when used with stdin\n")
			}
			// check stdout is console?
			if isTTY(os.Stdout) && !opts.stdoutForce {
				fmt.Fprintf(os.Stderr, "Error: stdout is a console, aborting. Use -c to force.\n")
				os.Exit(1)
			}
			var outData []byte
			if opts.legacy {
				outData = encodeLegacy(data)
			} else {
				// for stdin, isStdin true
				outData = encodeFrame(data, opts, true)
			}
			// Write to stdout or explicitOutput or null?
			if explicitOutput != "" {
				if explicitOutput == "null" || explicitOutput == "stdout" || explicitOutput == "-" {
					// handle accordingly
					if explicitOutput == "null" {
						// discard
					} else {
						os.Stdout.Write(outData)
					}
				} else {
					// explicit file
					if fileExists(explicitOutput) && !opts.force {
						if !promptOverwrite(explicitOutput) {
							os.Exit(1)
						}
					}
					os.WriteFile(explicitOutput, outData, 0644)
					if opts.remove {
						// remove stdin? not a file, so error? original prints Remove error for stdin
						fmt.Fprintf(os.Stderr, "Error 50 : Remove error : stdin: No such file or directory \n")
						// still write output then exit?
						// we already wrote, now just print error but not exit failure? original still wrote compressed data to stdout despite error?
						// For stdin with --rm, it prints error to stderr but still outputs compressed to stdout
						os.Stdout.Write(outData) // already written? Actually for stdin compress without -c and stdout not file, data already to stdout? But we handled explicitOutput case, not this.
					}
				}
			} else {
