				j := 1
				for j < len(arg) && arg[j] >= '0' && arg[j] <= '9' {
					j++
				}
				levelStr := arg[1:j]
				if lvl, err := strconv.Atoi(levelStr); err == nil {
					opts.level = lvl
				}
				// remaining chars
				remaining := arg[j:]
				for _, c := range remaining {
					switch c {
					case 'f':
						opts.force = true
					case 'k':
						opts.keep = true
						opts.remove = false
					case 'c':
						opts.stdoutForce = true
					case 'd':
						opts.decompress = true
					case 't':
						opts.testMode = true
					case 'm':
						opts.multiple = true
					case 'r':
