						needVersion = true
					case 'B':
						// B with no param? remaining includes B?
						// This case shouldn't happen because we already consumed digits, but if arg is like "-9B4" ??
						// handle generically
					default:
						unknownFlag = true
					}
				}
			} else {
				// process each char
				// need to handle flags that take param
				for k := 1; k < len(arg); {
					c := arg[k]
					switch c {
					case 'd':
						opts.decompress = true
						k++
					case 'f':
						opts.force = true
						k++
					case 'k':
						opts.keep = true
						opts.remove = false
						k++
					case 'c':
						opts.stdoutForce = true
						k++
					case 't':
						opts.testMode = true
						k++
					case 'm':
						opts.multiple = true
						k++
					case 'r':
						opts.recursive = true
						opts.multiple = true
						k++
					case 'l':
						opts.legacy = true
						k++
					case 'z':
						opts.forceCompress = true
						k++
					case 'v':
						opts.verbose = true
						k++
					case 'q':
						opts.quiet++
						k++
					case 'h':
						needHelpShort = true
						k++
					case 'H':
						needHelpLong = true
						k++
					case 'V':
						needVersion = true
						k++
					case 'B':
						// B may be followed by param in same arg
						param := ""
						if k+1 < len(arg) {
							param = arg[k+1:]
							k = len(arg)
						} else {
							// check next arg
							if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
								// but need to ensure not a file that looks like block size? We'll take it if it looks like block size?
								// For test, -B without param shouldn't consume file
								// So we check if next arg is 4-7 or contains K/M or numeric
								next := args[i+1]
								if next == "4" || next == "5" || next == "6" || next == "7" || strings.ContainsAny(next, "KMkm0123456789") {
