								if opts.quiet == 0 {
									var sizeStr string
									if v, ok := parseBlockSize(param); ok {
										if v < 1024 {
											sizeStr = fmt.Sprintf("%d bytes", v)
										} else if v < 1024*1024 {
											sizeStr = fmt.Sprintf("%d KB", v/1024)
										} else {
											sizeStr = fmt.Sprintf("%d KB", v/1024)
										}
										// mimic original: use predefined sizes for 64K etc
										switch param {
										case "4", "64K", "64KB", "64k", "64kb":
											sizeStr = "64 KB"
										case "5", "256K", "256KB":
											sizeStr = "256 KB"
										case "6", "1M", "1MB", "1024KB", "1024 KB":
											sizeStr = "1024 KB"
										case "7", "4M", "4MB", "4096KB":
											sizeStr = "4096 KB"
										}
										fmt.Fprintf(os.Stderr, "using blocks of size %s \n", sizeStr)
									}
								}
							}
						} else {
							// no param, maybe default? keep
							if opts.quiet == 0 {
								fmt.Fprintf(os.Stderr, "using blocks of size 64 KB \n")
							}
						}
						break // consumed rest
					case 'D':
						param := ""
						if k+1 < len(arg) {
							param = arg[k+1:]
							k = len(arg)
						} else {
							if i+1 < len(args) {
								param = args[i+1]
								i++
							} else {
								unknownFlag = true
								k++
								break
							}
							k++
						}
						opts.dictFile = param
						break
					case 'T':
						param := ""
						if k+1 < len(arg) {
							param = arg[k+1:]
							k = len(arg)
						} else {
							if i+1 < len(args) {
								param = args[i+1]
								i++
							}
							k++
						}
						if param != "" {
							if _, err := strconv.Atoi(param); err != nil {
								unknownFlag = true
							} else {
								// ignore threads
							}
						}
						break
					case 'b':
						// benchmark level
						param := ""
						if k+1 < len(arg) {
							param = arg[k+1:]
							k = len(arg)
						} else {
							if i+1 < len(args) {
								param = args[i+1]
								i++
							}
							k++
						}
						opts.benchmark = true
						if param != "" {
							if _, err := strconv.Atoi(param); err != nil {
								unknownFlag = true
							}
						}
						break
					case 'e':
						param := ""
						if k+1 < len(arg) {
							param = arg[k+1:]
							k = len(arg)
						} else {
							if i+1 < len(args) {
								param = args[i+1]
								i++
							}
							k++
						}
						if param != "" {
							if _, err := strconv.Atoi(param); err != nil {
								unknownFlag = true
							}
						}
						break
					case 'i':
						param := ""
						if k+1 < len(arg) {
							param = arg[k+1:]
							k = len(arg)
						} else {
							if i+1 < len(args) {
								param = args[i+1]
								i++
							}
							k++
						}
						if param != "" {
							// ignore
						}
						break
					case '1', '2', '3', '4', '5', '6', '7', '8', '9', '0':
						// digit after dash without other flag? Should be level but already handled? This path is for non-leading digit like "-f1"?
						// Treat as level?
						// Collect digits
						start := k
						for k < len(arg) && arg[k] >= '0' && arg[k] <= '9' {
							k++
						}
						levelStr := arg[start:k]
						if lvl, err := strconv.Atoi(levelStr); err == nil {
							opts.level = lvl
						}
					default:
						unknownFlag = true
						k++
					}
				}
			}
		} else {
			positional = append(positional, arg)
		}
		i++
	}
	if needVersion {
		printVersion()
		os.Exit(0)
	}
	if needHelpShort {
		printHelp(prog, false)
		os.Exit(0)
	}
	if needHelpLong {
		printHelp(prog, true)
		os.Exit(0)
	}
	if unknownFlag {
		printIncorrect(prog)
		os.Exit(1)
	}
	// handle --list mode
	if opts.listMode {
		// listFiles contains files to list; if inList and positional also has files, combine?
		// Actually positional contains files after --list if we didn't use inList correctly
		// If listFiles empty, use positional
		if len(listFiles) == 0 {
			listFiles = positional
		}
		if len(listFiles) == 0 {
			printIncorrect(prog)
			os.Exit(1)
		}
		// check Verbose for list
		verboseList := opts.verbose
		if verboseList {
			fmt.Fprintln(os.Stderr, versionStr)
		}
		// For non-verbose, header to stdout
		if !verboseList {
			fmt.Fprintln(os.Stdout, "    Frames           Type Block  Compressed  Uncompressed    Ratio   Filename")
		}
		for idx, fname := range listFiles {
			data, err := os.ReadFile(fname)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s: No such file or directory \n", fname)
				os.Exit(1)
			}
			// determine file type
			// Try to parse frame
			var frameType string = "LZ4Frame"
			var blockStr string = "B4I"
			var compressed float64 = float64(len(data))
			var uncompressedStr string = "-"
			var ratioStr string = "-"
			var blockCode int = 4
			// detect legacy
			if len(data) >= 4 && binary.LittleEndian.Uint32(data[0:4]) == 0x184C2102 {
				frameType = "LegacyFrame"
				blockStr = "-"
			} else if len(data) >= 4 && binary.LittleEndian.Uint32(data[0:4]) == 0x184D2A04 {
				// parse header to get block code, frame checksum etc
				if len(data) >= 7 {
					flg := data[4]
					bd := data[5]
					code := int(bd>>4) & 0x7
					if code >= 4 && code <= 7 {
						blockCode = code
					}
					indep := (flg>>5)&1 == 1
					_ = indep
					// check content size
					hasCS := (flg>>3)&1 == 1
					if hasCS {
						if len(data) >= 15 {
							cs := binary.LittleEndian.Uint64(data[7:15])
							uncompressedStr = fmt.Sprintf("%d.00", cs) // but original shows 6.00 for 6, etc. Use .2f?
							// Actually original shows 6.00 etc with 2 decimals? For cs with size, they show e.g., 6.00
							// But compressed is 33.00, uncompressed 6.00
							// For ratio, compute
							if cs != 0 {
								ratio := float64(len(data)) * 100 / float64(cs)
								ratioStr = fmt.Sprintf("%.2f%%", ratio)
							}
						}
					}
					// block string
					suffix := "I"
					if (flg>>5)&1 == 0 {
						suffix = "D"
					}
					blockStr = fmt.Sprintf("B%d%s", blockCode, suffix)
				}
			} else {
				fmt.Fprintf(os.Stderr, "Error 44 : Unrecognized header : file cannot be decoded \n")
				os.Exit(44)
			}
			if verboseList {
				// print per file verbose
				fmt.Fprintf(os.Stdout, "%s(%d/%d)\n", fname, idx+1, len(listFiles))
				fmt.Fprintln(os.Stdout, "     Frame           Type Block Checksum           Compressed         Uncompressed     Ratio")
				// need to decide checksum display: if no-frame-crc? For now XXH32 if frame checksum enabled else "-"
				checksumStr := "XXH32"
				// check flg for frame checksum
				if len(data) >= 7 {
					flg := data[4]
					if (flg>>2)&1 == 0 {
						checksumStr = "-"
					}
					if binary.LittleEndian.Uint32(data[0:4]) == 0x184C2102 {
						checksumStr = "-"
					}
				}
				// compressed size
				csDisplay := fmt.Sprintf("%d", len(data))
				ucDisplay := uncompressedStr
				if ucDisplay == "-" {
					ucDisplay = "-"
				}
				ratioDisplay := ratioStr
				if ratioDisplay == "-" {
					ratioDisplay = "-"
				}
				// Format line
				fmt.Fprintf(os.Stdout, "         1       %s   %s    %s%19s%19s%10s\n", frameType, blockStr, checksumStr, csDisplay, ucDisplay, ratioDisplay)
				fmt.Fprintln(os.Stdout, "")
			} else {
				// non-verbose
				// compressed formatted as float with 2 decimals?
				compressedStr := fmt.Sprintf("%.2f", compressed)
				// uncompressed already string or "-"
				// Need to format with widths?
				// Use similar to original: B4I field width etc
				// We'll use printf with widths
				// Original line: "         1       LZ4Frame   B4I      373.00             -        -   sample.txt.lz4"
				// We can approximate with:
				fmt.Fprintf(os.Stdout, "%10d       %s   %s%10s%13s%10s   %s\n", 1, frameType, blockStr, compressedStr, uncompressedStr, ratioStr, fname)
				// But need to ensure compressedStr is 6? We'll just use formatting that matches typical widths
				// Alternative: Use exact formatting from original via manual
				// Let's do:
				// For frame type width 8, block width 3, etc
			}
		}
		os.Exit(0)
	}
	// handle benchmark
	if opts.benchmark {
		// stub: print benchmark output similar to original
		// If no files, use stdin?
		if len(positional) == 0 {
