			os.Exit(0)
		}
		for _, f := range positional {
			// quick benchmark simulation
			data, err := os.ReadFile(f)
			if err != nil {
				continue
			}
			// simulate benchmark lines
			// Original prints with \r and shows compression ratio etc
			// We'll just print a simple line
			fmt.Fprintf(os.Stderr, "Benchmarking %s : %d bytes\n", f, len(data))
			// mimic output: " 1# ..."? We'll just output minimal
		}
		os.Exit(0)
	}
	// Determine inputs
	// If multiple or recursive, positional are all inputs, no output arg
	// Else if len(positional)==2, first is input, second is output
	// Else if len(positional)==1, it's input, output auto
	// Else if len(positional)==0, input is stdin
	var inputs []string
	var explicitOutput string
	if opts.multiple || opts.recursive {
		inputs = positional
		// output arg not allowed
	} else {
		if len(positional) == 2 {
			inputs = []string{positional[0]}
			explicitOutput = positional[1]
		} else if len(positional) == 1 {
			inputs = []string{positional[0]}
		} else if len(positional) == 0 {
			inputs = []string{} // stdin
		} else if len(positional) > 2 {
			// too many without -m : should error? Original prints "Incorrect parameters" ?
			// For now, treat as error if not multiple and >2
			// But for our test, `lz4 file1 file2` without -m is considered single input file1 and output file2? We handled 2. For >2 without -m, error.
			printIncorrect(prog)
			os.Exit(1)
		}
	}
	// Expand recursive
	if opts.recursive {
		var expanded []string
		for _, p := range inputs {
			fi, err := os.Stat(p)
			if err != nil {
