							os.Exit(1)
						}
					}
					os.WriteFile(explicitOutput, decoded, 0644)
				}
			} else {
				os.Stdout.Write(decoded)
			}
		}
		os.Exit(0)
	}
	// Handle multiple inputs
	if opts.multiple || opts.recursive {
		if len(inputs) == 0 {
			printIncorrect(prog)
			os.Exit(1)
		}
		exitCode := 0
		for _, inFile := range inputs {
			// check if input is "-" stdin
			var data []byte
			var err error
			isStdin := false
			if inFile == "-" {
