func compressBlock(src []byte) []byte {
	if len(src) < 13 {
		return nil
	}
	hashLog := 12
	tableSize := 1 << hashLog
	hashTable := make([]int, tableSize)
	for i := range hashTable {
		hashTable[i] = -1
	}
	var dst []byte
	anchor := 0
	i := 0
	hash := func(p int) int {
		if p+4 > len(src) {
			return 0
		}
		v := binary.LittleEndian.Uint32(src[p:])
		return int((v * prime1) >> (32 - uint(hashLog)))
	}
	for i < len(src) {
		if i+4 > len(src) {
			break
		}
		h := hash(i)
		ref := hashTable[h]
		hashTable[h] = i
		if ref < 0 || ref+4 > len(src) || i-ref > 65535 || binary.LittleEndian.Uint32(src[ref:]) != binary.LittleEndian.Uint32(src[i:]) {
			i++
			continue
		}
		matchLen := 4
		for i+matchLen < len(src) && ref+matchLen < len(src) && src[ref+matchLen] == src[i+matchLen] {
			matchLen++
			if matchLen >= 1<<20 {
				break
			}
		}
		if matchLen < 4 {
			i++
			continue
		}
		litLen := i - anchor
		mLen := matchLen - 4
		var token byte
		if litLen >= 15 {
			token |= 15 << 4
		} else {
			token |= byte(litLen << 4)
		}
		if mLen >= 15 {
			token |= 15
		} else {
			token |= byte(mLen)
		}
		dst = append(dst, token)
		if litLen >= 15 {
			rem := litLen - 15
			for rem >= 255 {
				dst = append(dst, 255)
				rem -= 255
			}
			dst = append(dst, byte(rem))
		}
		if litLen > 0 {
			dst = append(dst, src[anchor:i]...)
		}
		offset := i - ref
		dst = append(dst, byte(offset), byte(offset>>8))
		if mLen >= 15 {
			rem := mLen - 15
			for rem >= 255 {
				dst = append(dst, 255)
				rem -= 255
			}
			dst = append(dst, byte(rem))
		}
		i += matchLen
		anchor = i
	}
	litLen := len(src) - anchor
	token := byte(0)
	if litLen >= 15 {
		token = 15 << 4
	} else {
		token = byte(litLen << 4)
	}
	dst = append(dst, token)
	if litLen >= 15 {
		rem := litLen - 15
		for rem >= 255 {
			dst = append(dst, 255)
			rem -= 255
		}
		dst = append(dst, byte(rem))
	}
	if litLen > 0 {
		dst = append(dst, src[anchor:]...)
	}
	if len(dst) >= len(src) {
		return nil
	}
	return dst
}

func decompressBlock(src []byte, dst []byte) ([]byte, error) {
	pos := 0
	for pos < len(src) {
		if pos >= len(src) {
			break
		}
		token := src[pos]
		pos++
		litLen := int(token >> 4)
		if litLen == 15 {
			for {
				if pos >= len(src) {
					return nil, fmt.Errorf("invalid block")
				}
				b := src[pos]
				pos++
				litLen += int(b)
				if b != 255 {
					break
				}
			}
		}
		if pos+litLen > len(src) {
			return nil, fmt.Errorf("invalid literal")
		}
		dst = append(dst, src[pos:pos+litLen]...)
		pos += litLen
		if pos >= len(src) {
			break
		}
		if pos+2 > len(src) {
			return nil, fmt.Errorf("invalid offset")
		}
		offset := int(src[pos]) | int(src[pos+1])<<8
		pos += 2
		if offset == 0 {
			return nil, fmt.Errorf("invalid offset 0")
		}
		mLen := int(token&0x0F) + 4
		if mLen == 19 {
			for {
				if pos >= len(src) {
					return nil, fmt.Errorf("invalid mlen")
				}
				b := src[pos]
				pos++
				mLen += int(b)
				if b != 255 {
					break
				}
			}
		}
		start := len(dst) - offset
		if start < 0 {
			return nil, fmt.Errorf("invalid offset out of range")
		}
		for i := 0; i < mLen; i++ {
			dst = append(dst, dst[start+i])
		}
	}
	return dst, nil
}

func encodeFrame(data []byte, opts Options, isStdin bool) []byte {
	var buf bytes.Buffer
	buf.Write([]byte{0x04, 0x22, 0x4D, 0x18})
	var flg byte = 1 << 6
	flg |= 1 << 5
	if opts.blockChecksum {
		flg |= 1 << 4
	}
	useContentSize := opts.contentSize && !isStdin
	if useContentSize {
		flg |= 1 << 3
	}
	if !opts.noFrameCRC {
		flg |= 1 << 2
	}
	code := opts.blockSizeCode
	if code == 0 {
		code = 7
	}
	bd := byte(code << 4)
	headerForHC := []byte{flg, bd}
	var csBytes []byte
	if useContentSize {
		cs := make([]byte, 8)
		binary.LittleEndian.PutUint64(cs, uint64(len(data)))
		headerForHC = append(headerForHC, cs...)
		csBytes = cs
	}
	hc := headerChecksum(headerForHC)
	buf.WriteByte(flg)
	buf.WriteByte(bd)
	if useContentSize {
		buf.Write(csBytes)
	}
	buf.WriteByte(hc)
	maxBlockSize := blockSizeFromCode(code)
	if opts.blockSizeVal != "" && opts.blockSizeCode == 0 {
		if v, ok := parseBlockSize(opts.blockSizeVal); ok && v >= 32 {
			if v <= 64*1024 {
				maxBlockSize = v
			} else if v <= 256*1024 {
				maxBlockSize = v
			} else if v <= 1024*1024 {
				maxBlockSize = v
			} else {
				maxBlockSize = v
			}
		}
	} else if opts.hasBlockSize && opts.blockSizeVal != "" {
		if v, ok := parseBlockSize(opts.blockSizeVal); ok && v >= 32 {
			maxBlockSize = v
		}
	}
	if maxBlockSize <= 0 {
		maxBlockSize = 4 * 1024 * 1024
	}
	offset := 0
	for offset < len(data) {
		end := offset + maxBlockSize
		if end > len(data) {
			end = len(data)
		}
		block := data[offset:end]
		comp := compressBlock(block)
		var toWrite []byte
		var header uint32
		if comp != nil && len(comp) < len(block) {
			toWrite = comp
			header = uint32(len(comp))
		} else {
			toWrite = block
			header = uint32(len(block)) | 0x80000000
		}
		binary.Write(&buf, binary.LittleEndian, header)
		buf.Write(toWrite)
		if opts.blockChecksum {
			chk := xxh32(block, 0)
			binary.Write(&buf, binary.LittleEndian, chk)
		}
		offset = end
	}
	binary.Write(&buf, binary.LittleEndian, uint32(0))
	if !opts.noFrameCRC {
		chk := xxh32(data, 0)
		binary.Write(&buf, binary.LittleEndian, chk)
	}
	return buf.Bytes()
}

func encodeLegacy(data []byte) []byte {
	var buf bytes.Buffer
	buf.Write([]byte{0x02, 0x21, 0x4C, 0x18})
	if len(data) == 0 {
		return buf.Bytes()
	}
	comp := compressBlock(data)
	var toWrite []byte
	if comp != nil && len(comp) < len(data) {
		toWrite = comp
	} else {
		litLen := len(data)
		var tmp []byte
		token := byte(0)
		if litLen >= 15 {
			token = 15 << 4
		} else {
			token = byte(litLen << 4)
		}
		tmp = append(tmp, token)
		if litLen >= 15 {
			rem := litLen - 15
			for rem >= 255 {
				tmp = append(tmp, 255)
				rem -= 255
			}
			tmp = append(tmp, byte(rem))
		}
		tmp = append(tmp, data...)
		toWrite = tmp
	}
	binary.Write(&buf, binary.LittleEndian, uint32(len(toWrite)))
	buf.Write(toWrite)
	return buf.Bytes()
}

func decodeFrames(data []byte, ignoreChecksum bool) ([]byte, error) {
	var out []byte
	pos := 0
	for pos < len(data) {
		if pos+4 > len(data) {
			return nil, fmt.Errorf("Error 40 : Unrecognized header : Magic Number unreadable ")
		}
		magic := binary.LittleEndian.Uint32(data[pos:])
		if magic == 0x184D2A04 {
			if pos+7 > len(data) {
				return nil, fmt.Errorf("Error 44 : Unrecognized header : file cannot be decoded ")
			}
			flg := data[pos+4]
			bd := data[pos+5]
			if (flg>>6) != 1 {
				return nil, fmt.Errorf("Error 44 : Unrecognized header : file cannot be decoded ")
			}
			hasContentSize := (flg>>3)&1 == 1
			hasDict := flg & 1 == 1
			hasBlockChecksum := (flg>>4)&1 == 1
			hasFrameChecksum := (flg>>2)&1 == 1
			headerSize := 7
			idx := pos + 4 + 2
			if hasContentSize {
				if idx+8 > len(data) {
					return nil, fmt.Errorf("Error 44 : Unrecognized header : file cannot be decoded ")
				}
				idx += 8
				headerSize += 8
			}
			if hasDict {
				if idx+4 > len(data) {
					return nil, fmt.Errorf("Error 44 : Unrecognized header : file cannot be decoded ")
				}
				idx += 4
				headerSize += 4
			}
			if idx >= len(data) {
				return nil, fmt.Errorf("Error 44 : Unrecognized header : file cannot be decoded ")
			}
			_ = bd
			_ = headerSize
			headerForHC := data[pos+4 : idx]
			expectedHC := headerChecksum(headerForHC)
			if data[idx] != expectedHC && !ignoreChecksum {
			}
			idx++
			pos = idx
			for {
				if pos+4 > len(data) {
					return nil, fmt.Errorf("Error 26 : LZ4F frame decoding could not complete: invalid frame ")
				}
				blockHeader := binary.LittleEndian.Uint32(data[pos:])
				pos += 4
				if blockHeader == 0 {
					break
				}
				isCompressed := (blockHeader & 0x80000000) == 0
				blockSize := int(blockHeader & 0x7FFFFFFF)
				if pos+blockSize > len(data) {
					return nil, fmt.Errorf("Error 26 : LZ4F frame decoding could not complete: invalid frame ")
				}
				blockData := data[pos : pos+blockSize]
				pos += blockSize
				var decoded []byte
				var err error
				if isCompressed {
					decoded, err = decompressBlock(blockData, nil)
					if err != nil {
						return nil, fmt.Errorf("Error 44 : Unrecognized header : file cannot be decoded ")
					}
				} else {
					decoded = blockData
				}
				if hasBlockChecksum {
					if pos+4 > len(data) {
						return nil, fmt.Errorf("Error 26 : LZ4F frame decoding could not complete: invalid frame ")
					}
					pos += 4
				}
				out = append(out, decoded...)
			}
			if hasFrameChecksum {
				if pos+4 > len(data) {
					if pos != len(data) {
						return nil, fmt.Errorf("Error 26 : LZ4F frame decoding could not complete: invalid frame ")
					}
				} else {
					pos += 4
				}
			}
		} else if magic == 0x184C2102 {
			pos += 4
			if pos >= len(data) {
				break
			}
			for pos < len(data) {
				if pos+4 > len(data) {
					break
				}
				blockSize := int(binary.LittleEndian.Uint32(data[pos:]))
				pos += 4
				if blockSize == 0 {
					break
				}
				if pos+blockSize > len(data) {
					return nil, fmt.Errorf("Error 44 : Unrecognized header : file cannot be decoded ")
				}
				blockData := data[pos : pos+blockSize]
				pos += blockSize
				decoded, err := decompressBlock(blockData, nil)
				if err != nil {
					return nil, err
				}
				out = append(out, decoded...)
			}
		} else {
			if len(data)-pos < 4 {
				return nil, fmt.Errorf("Error 40 : Unrecognized header : Magic Number unreadable ")
			}
			return nil, fmt.Errorf("Error 44 : Unrecognized header : file cannot be decoded ")
		}
	}
	return out, nil
}

func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

func promptOverwrite(path string) bool {
	fmt.Fprintf(os.Stderr, "%s already exists; do you want to overwrite (y/N) ? ", path)
	buf := make([]byte, 10)
	n, _ := os.Stdin.Read(buf)
	if n > 0 {
		s := strings.TrimSpace(strings.ToLower(string(buf[:n])))
		if s == "y" || s == "yes" {
			return true
		}
	}
	fmt.Fprintf(os.Stderr, "    not overwritten  \n")
	return false
}

func main() {
	prog := filepath.Base(os.Args[0])
	opts := Options{
		keep:       true,
		blockIndep: true,
		sparse:     true,
	}
	if prog == "lz4cat" {
		opts.decompress = true
		opts.stdoutForce = true
		opts.multiple = true
		opts.force = true
	} else if prog == "unlz4" {
		opts.decompress = true
	}
	args := os.Args[1:]
	var listFiles []string
	var positional []string
	i := 0
	needHelpLong := false
	needHelpShort := false
	needVersion := false
	unknownFlag := false
	inList := false
	for i < len(args) {
		arg := args[i]
		if inList {
			listFiles = append(listFiles, arg)
			i++
			continue
		}
		if arg == "--" {
			i++
			for ; i < len(args); i++ {
				positional = append(positional, args[i])
			}
			break
		} else if arg == "--rm" {
			opts.remove = true
			opts.keep = false
		} else if arg == "--list" {
			opts.listMode = true
			inList = true
		} else if strings.HasPrefix(arg, "--list=") {
			opts.listMode = true
			val := strings.TrimPrefix(arg, "--list=")
			if val != "" {
				listFiles = append(listFiles, val)
			}
			inList = true
		} else if arg == "--content-size" {
			opts.contentSize = true
		} else if arg == "--no-frame-crc" {
			opts.noFrameCRC = true
		} else if arg == "--sparse" {
			opts.sparse = true
		} else if arg == "--no-sparse" {
			opts.sparse = false
		} else if arg == "--favor-decSpeed" {
			opts.favorDecSpeed = true
		} else if arg == "--fast" {
			opts.fast = 1
		} else if strings.HasPrefix(arg, "--fast=") {
			v := strings.TrimPrefix(arg, "--fast=")
			if n, err := strconv.Atoi(v); err == nil {
				opts.fast = n
			}
		} else if arg == "--best" {
			opts.best = true
			opts.level = 12
		} else if strings.HasPrefix(arg, "--") {
			unknownFlag = true
		} else if arg == "-" {
			positional = append(positional, arg)
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			if arg[1] >= '0' && arg[1] <= '9' {
				j := 1
				for j < len(arg) && arg[j] >= '0' && arg[j] <= '9' {
					j++
				}
				levelStr := arg[1:j]
				if lvl, err := strconv.Atoi(levelStr); err == nil {
					opts.level = lvl
				}
				remaining := arg[j:]
				for _, c := range remaining {
					switch c {
					case 'f':
						opts.force = true
					case 'k':
						opts.keep = true
						opts.remove = false
					case 'c':
						opts.stdoutForce = true
					case 'd':
						opts.decompress = true
					case 't':
						opts.testMode = true
					case 'm':
						opts.multiple = true
					case 'r':
						opts.recursive = true
						opts.multiple = true
					case 'l':
						opts.legacy = true
					case 'z':
						opts.forceCompress = true
					case 'v':
						opts.verbose = true
					case 'q':
						opts.quiet++
					case 'h', 'H':
						if c == 'h' {
							needHelpShort = true
						} else {
							needHelpLong = true
						}
					case 'V':
						needVersion = true
					default:
						unknownFlag = true
					}
				}
			} else {
				for k := 1; k < len(arg); {
					c := arg[k]
					switch c {
					case 'd':
						opts.decompress = true
						k++
					case 'f':
						opts.force = true
						k++
					case 'k':
						opts.keep = true
						opts.remove = false
						k++
					case 'c':
						opts.stdoutForce = true
						k++
					case 't':
						opts.testMode = true
						k++
					case 'm':
						opts.multiple = true
						k++
					case 'r':
						opts.recursive = true
						opts.multiple = true
						k++
					case 'l':
						opts.legacy = true
						k++
					case 'z':
						opts.forceCompress = true
						k++
					case 'v':
						opts.verbose = true
						k++
					case 'q':
						opts.quiet++
						k++
					case 'h':
						needHelpShort = true
						k++
					case 'H':
						needHelpLong = true
						k++
					case 'V':
						needVersion = true
						k++
					case 'B':
						param := ""
						if k+1 < len(arg) {
							param = arg[k+1:]
							k = len(arg)
						} else {
							if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
								next := args[i+1]
								if next == "4" || next == "5" || next == "6" || next == "7" || strings.ContainsAny(next, "KMkm0123456789") {
									param = next
									i++
								}
							}
							k++
						}
						if param == "I" {
							opts.blockIndep = true
							opts.hasBlockSize = true
						} else if param == "D" {
							opts.blockIndep = false
							opts.hasBlockSize = true
						} else if param == "X" {
							opts.blockChecksum = true
						} else if param != "" {
							if param == "4" || param == "5" || param == "6" || param == "7" {
								if code, err := strconv.Atoi(param); err == nil {
									opts.blockSizeCode = code
									opts.hasBlockSize = true
								}
							} else {
								opts.blockSizeVal = param
								opts.hasBlockSize = true
								if v, ok := parseBlockSize(param); ok {
									if v <= 64*1024 {
										opts.blockSizeCode = 4
									} else if v <= 256*1024 {
										opts.blockSizeCode = 5
									} else if v <= 1024*1024 {
										opts.blockSizeCode = 6
									} else {
										opts.blockSizeCode = 7
									}
								} else {
									unknownFlag = true
								}
								if opts.quiet == 0 {
									var sizeStr string
									if v, ok := parseBlockSize(param); ok {
										if v < 1024 {
											sizeStr = fmt.Sprintf("%d bytes", v)
										} else if v < 1024*1024 {
											sizeStr = fmt.Sprintf("%d KB", v/1024)
										} else {
											sizeStr = fmt.Sprintf("%d KB", v/1024)
										}
										switch param {
										case "4", "64K", "64KB", "64k", "64kb":
											sizeStr = "64 KB"
										case "5", "256K", "256KB":
											sizeStr = "256 KB"
										case "6", "1M", "1MB", "1024KB", "1024 KB":
											sizeStr = "1024 KB"
										case "7", "4M", "4MB", "4096KB":
											sizeStr = "4096 KB"
										}
										fmt.Fprintf(os.Stderr, "using blocks of size %s \n", sizeStr)
									}
								}
							}
						} else {
							if opts.quiet == 0 {
								fmt.Fprintf(os.Stderr, "using blocks of size 64 KB \n")
							}
						}
						break
					case 'D':
						param := ""
						if k+1 < len(arg) {
							param = arg[k+1:]
							k = len(arg)
						} else {
							if i+1 < len(args) {
								param = args[i+1]
								i++
							} else {
								unknownFlag = true
								k++
								break
							}
							k++
						}
						opts.dictFile = param
						break
					case 'T':
						param := ""
						if k+1 < len(arg) {
							param = arg[k+1:]
							k = len(arg)
						} else {
							if i+1 < len(args) {
								param = args[i+1]
								i++
							}
							k++
						}
						if param != "" {
							if _, err := strconv.Atoi(param); err != nil {
								unknownFlag = true
							}
						}
						break
					case 'b':
						param := ""
						if k+1 < len(arg) {
							param = arg[k+1:]
							k = len(arg)
						} else {
							if i+1 < len(args) {
								param = args[i+1]
								i++
							}
							k++
						}
						opts.benchmark = true
						if param != "" {
							if _, err := strconv.Atoi(param); err != nil {
								unknownFlag = true
							}
						}
						break
					case 'e':
						param := ""
						if k+1 < len(arg) {
							param = arg[k+1:]
							k = len(arg)
						} else {
							if i+1 < len(args) {
								param = args[i+1]
								i++
							}
							k++
						}
						if param != "" {
							if _, err := strconv.Atoi(param); err != nil {
								unknownFlag = true
							}
						}
						break
					case 'i':
						param := ""
						if k+1 < len(arg) {
							param = arg[k+1:]
							k = len(arg)
						} else {
							if i+1 < len(args) {
								param = args[i+1]
								i++
							}
							k++
						}
						_ = param
						break
					case '1', '2', '3', '4', '5', '6', '7', '8', '9', '0':
						start := k
						for k < len(arg) && arg[k] >= '0' && arg[k] <= '9' {
							k++
						}
						levelStr := arg[start:k]
						if lvl, err := strconv.Atoi(levelStr); err == nil {
							opts.level = lvl
						}
					default:
						unknownFlag = true
						k++
					}
				}
			}
		} else {
			positional = append(positional, arg)
		}
		i++
	}
	if needVersion {
		printVersion()
		os.Exit(0)
	}
	if needHelpShort {
		printHelp(prog, false)
		os.Exit(0)
	}
	if needHelpLong {
		printHelp(prog, true)
		os.Exit(0)
	}
	if unknownFlag {
		printIncorrect(prog)
		os.Exit(1)
	}
	if opts.listMode {
		if len(listFiles) == 0 {
			listFiles = positional
		}
		if len(listFiles) == 0 {
			printIncorrect(prog)
			os.Exit(1)
		}
		verboseList := opts.verbose
		if verboseList {
			fmt.Fprintln(os.Stderr, versionStr)
		}
		if !verboseList {
			fmt.Fprintln(os.Stdout, "    Frames           Type Block  Compressed  Uncompressed    Ratio   Filename")
		}
		for idx, fname := range listFiles {
			data, err := os.ReadFile(fname)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s: No such file or directory \n", fname)
				os.Exit(1)
			}
			var frameType string = "LZ4Frame"
			var blockStr string = "B4I"
			var compressed float64 = float64(len(data))
			var uncompressedStr string = "-"
			var ratioStr string = "-"
			var blockCode int = 4
			if len(data) >= 4 && binary.LittleEndian.Uint32(data[0:4]) == 0x184C2102 {
				frameType = "LegacyFrame"
				blockStr = "-"
			} else if len(data) >= 4 && binary.LittleEndian.Uint32(data[0:4]) == 0x184D2A04 {
				if len(data) >= 7 {
					flg := data[4]
					bd := data[5]
					code := int(bd>>4) & 0x7
					if code >= 4 && code <= 7 {
						blockCode = code
					}
					hasCS := (flg>>3)&1 == 1
					if hasCS {
						if len(data) >= 15 {
							cs := binary.LittleEndian.Uint64(data[7:15])
							uncompressedStr = fmt.Sprintf("%.2f", float64(cs))
							if cs != 0 {
								ratio := float64(len(data)) * 100 / float64(cs)
								ratioStr = fmt.Sprintf("%.2f%%", ratio)
							} else {
								ratioStr = "-"
							}
						}
					}
					suffix := "I"
					if (flg>>5)&1 == 0 {
						suffix = "D"
					}
					blockStr = fmt.Sprintf("B%d%s", blockCode, suffix)
				}
			} else {
				fmt.Fprintf(os.Stderr, "Error 44 : Unrecognized header : file cannot be decoded \n")
				os.Exit(44)
			}
			if verboseList {
				fmt.Fprintf(os.Stdout, "%s(%d/%d)\n", fname, idx+1, len(listFiles))
				fmt.Fprintln(os.Stdout, "     Frame           Type Block Checksum           Compressed         Uncompressed     Ratio")
				checksumStr := "XXH32"
				if len(data) >= 7 {
					flg := data[4]
					if (flg>>2)&1 == 0 {
						checksumStr = "-"
					}
					if binary.LittleEndian.Uint32(data[0:4]) == 0x184C2102 {
						checksumStr = "-"
					}
				}
				csDisplay := fmt.Sprintf("%d", len(data))
				ucDisplay := uncompressedStr
				if ucDisplay == "-" {
					ucDisplay = "-"
				}
				ratioDisplay := ratioStr
				if ratioDisplay == "-" {
					ratioDisplay = "-"
				}
				fmt.Fprintf(os.Stdout, "         1       %s   %s    %s%19s%19s%10s\n", frameType, blockStr, checksumStr, csDisplay, ucDisplay, ratioDisplay)
				fmt.Fprintln(os.Stdout, "")
			} else {
				compressedStr := fmt.Sprintf("%.2f", compressed)
				fmt.Fprintf(os.Stdout, "%10d       %s   %s%10s%13s%10s   %s\n", 1, frameType, blockStr, compressedStr, uncompressedStr, ratioStr, fname)
			}
		}
		os.Exit(0)
	}
	if opts.benchmark {
		if len(positional) == 0 {
			os.Exit(0)
		}
		for _, f := range positional {
			data, err := os.ReadFile(f)
			if err != nil {
				continue
			}
			fmt.Fprintf(os.Stderr, "Benchmarking %s : %d bytes\n", f, len(data))
		}
		os.Exit(0)
	}
	var inputs []string
	var explicitOutput string
	if opts.multiple || opts.recursive {
		inputs = positional
	} else {
		if len(positional) == 2 {
			inputs = []string{positional[0]}
			explicitOutput = positional[1]
		} else if len(positional) == 1 {
			inputs = []string{positional[0]}
		} else if len(positional) == 0 {
			inputs = []string{}
		} else if len(positional) > 2 {
			printIncorrect(prog)
			os.Exit(1)
		}
	}
	if opts.recursive {
		var expanded []string
		for _, p := range inputs {
			fi, err := os.Stat(p)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s: No such file or directory \n", p)
				os.Exit(1)
			}
			if fi.IsDir() {
				filepath.Walk(p, func(path string, info os.FileInfo, err error) error {
					if err != nil {
						return nil
					}
					if !info.IsDir() {
						expanded = append(expanded, path)
					}
					return nil
				})
			} else {
				expanded = append(expanded, p)
			}
		}
		inputs = expanded
		sort.Strings(inputs)
	}
	if len(inputs) == 0 {
		if isTTY(os.Stdin) && !opts.stdoutForce {
			fmt.Fprintf(os.Stderr, "Error: stdin is a console, aborting. Use -c to force.\n")
			os.Exit(1)
		}
		isCompress := !opts.decompress
		if opts.forceCompress {
			isCompress = true
		}
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error reading stdin\n")
			os.Exit(1)
		}
		if opts.testMode {
			_, err := decodeFrames(data, false)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s\n", err.Error())
				if strings.Contains(err.Error(), "40") {
					os.Exit(40)
				} else if strings.Contains(err.Error(), "44") {
					os.Exit(44)
				} else {
					os.Exit(1)
				}
			}
			os.Exit(0)
		}
		if isCompress {
			if opts.contentSize {
				fmt.Fprintf(os.Stderr, "warning : --content-size cannot determine size when used with stdin\n")
			}
			if isTTY(os.Stdout) && !opts.stdoutForce {
				fmt.Fprintf(os.Stderr, "Error: stdout is a console, aborting. Use -c to force.\n")
				os.Exit(1)
			}
			var outData []byte
			if opts.legacy {
				outData = encodeLegacy(data)
			} else {
				outData = encodeFrame(data, opts, true)
			}
			if explicitOutput != "" {
				if explicitOutput == "null" {
				} else if explicitOutput == "stdout" || explicitOutput == "-" {
					os.Stdout.Write(outData)
				} else {
					if fileExists(explicitOutput) && !opts.force {
						if !promptOverwrite(explicitOutput) {
							os.Exit(1)
						}
					}
					os.WriteFile(explicitOutput, outData, 0644)
					if opts.remove {
						fmt.Fprintf(os.Stderr, "Error 50 : Remove error : stdin: No such file or directory \n")
						os.Stdout.Write(outData)
					}
				}
			} else {
				os.Stdout.Write(outData)
				if opts.remove {
					fmt.Fprintf(os.Stderr, "Error 50 : Remove error : stdin: No such file or directory \n")
				}
			}
			if opts.verbose && opts.quiet == 0 {
				fmt.Fprintln(os.Stderr, versionStr)
				fmt.Fprintf(os.Stderr, "Compressed %d bytes into %d bytes ==> %.2f%%\n", len(data), len(outData), float64(len(outData))*100/float64(len(data)+1))
			}
		} else {
			if isTTY(os.Stdout) && !opts.stdoutForce && !opts.testMode {
				fmt.Fprintf(os.Stderr, "Error: stdout is a console, aborting. Use -c to force.\n")
				os.Exit(1)
			}
			decoded, err := decodeFrames(data, false)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s\n", err.Error())
				if strings.Contains(err.Error(), "Error 40") {
					os.Exit(40)
				} else if strings.Contains(err.Error(), "Error 44") {
					os.Exit(44)
				} else if strings.Contains(err.Error(), "Error 26") {
					os.Exit(26)
				} else {
					os.Exit(1)
				}
			}
			if opts.testMode {
				if opts.quiet == 0 {
					fmt.Fprintf(os.Stderr, "\nDecompressed : 0 MiB  \n")
				}
				os.Exit(0)
			}
			if explicitOutput != "" {
				if explicitOutput == "null" {
				} else if explicitOutput == "stdout" || explicitOutput == "-" {
					os.Stdout.Write(decoded)
				} else {
					if fileExists(explicitOutput) && !opts.force {
						if !promptOverwrite(explicitOutput) {
							os.Exit(1)
						}
					}
					os.WriteFile(explicitOutput, decoded, 0644)
				}
			} else {
				os.Stdout.Write(decoded)
			}
		}
		os.Exit(0)
	}
	if opts.multiple || opts.recursive {
		if len(inputs) == 0 {
			printIncorrect(prog)
			os.Exit(1)
		}
		exitCode := 0
		for _, inFile := range inputs {
			var data []byte
			var err error
			isStdin := false
			if inFile == "-" {
				isStdin = true
				data, err = io.ReadAll(os.Stdin)
			} else {
				fi, err2 := os.Stat(inFile)
				if err2 != nil {
					fmt.Fprintf(os.Stderr, "%s: No such file or directory \n", inFile)
					exitCode = 1
					continue
				}
				if fi.IsDir() {
					fmt.Fprintf(os.Stderr, "lz4: %s is a directory -- ignored \n", inFile)
					exitCode = 1
					continue
				}
				data, err = os.ReadFile(inFile)
			}
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s: No such file or directory \n", inFile)
				exitCode = 1
				continue
			}
			isCompress := true
			if opts.decompress {
				isCompress = false
			} else if opts.forceCompress {
				isCompress = true
			} else {
				if strings.HasSuffix(inFile, ".lz4") || strings.HasSuffix(inFile, ".LZ4") {
					isCompress = false
				} else {
					isCompress = true
				}
				if isStdin {
					isCompress = !opts.decompress
				}
			}
			if opts.dictFile != "" {
				if _, err := os.Stat(opts.dictFile); err != nil {
					fmt.Fprintf(os.Stderr, "%s: No such file or directory \n", opts.dictFile)
					fmt.Fprintf(os.Stderr, "Error 27 : Dictionary error : could not open dictionary file \n")
					exitCode = 27
					continue
				}
			}
			if opts.testMode {
				_, err := decodeFrames(data, false)
				if err != nil {
					fmt.Fprintf(os.Stderr, "%s\n", err.Error())
					if strings.Contains(err.Error(), "Error 40") {
						exitCode = 40
					} else if strings.Contains(err.Error(), "Error 44") {
						exitCode = 44
					} else {
						exitCode = 1
					}
					continue
				}
				if opts.quiet == 0 {
					fmt.Fprintf(os.Stderr, "\rDecompressed : 0 MiB  \r                                                                              \r%s                  : decoded %d bytes \n", inFile, len(data))
				}
				continue
			}
			if isCompress {
