func blockSizeFromCode(code int) int {
	switch code {
	case 4:
		return 64 * 1024
	case 5:
		return 256 * 1024
	case 6:
		return 1 * 1024 * 1024
	case 7:
		return 4 * 1024 * 1024
	default:
