const (
	prime1 = 2654435761
	prime2 = 2246822519
	prime3 = 3266489917
	prime4 = 668265263
	prime5 = 374761393
)

func rotl32(x uint32, r uint) uint32 {
	return (x << r) | (x >> (32 - r))
}

func xxh32(data []byte, seed uint32) uint32 {
	length := len(data)
	var h32 uint32
	p := 0
	if length >= 16 {
		v1 := seed + prime1 + prime2
		v2 := seed + prime2
		v3 := seed
		v4 := seed - prime1
		limit := length - 16
		for p <= limit {
			v1 += uint32(binary.LittleEndian.Uint32(data[p:])) * prime2
			v1 = rotl32(v1, 13)
			v1 *= prime1
			p += 4
			v2 += uint32(binary.LittleEndian.Uint32(data[p:])) * prime2
			v2 = rotl32(v2, 13)
			v2 *= prime1
			p += 4
			v3 += uint32(binary.LittleEndian.Uint32(data[p:])) * prime2
			v3 = rotl32(v3, 13)
			v3 *= prime1
			p += 4
			v4 += uint32(binary.LittleEndian.Uint32(data[p:])) * prime2
			v4 = rotl32(v4, 13)
			v4 *= prime1
			p += 4
		}
		h32 = rotl32(v1, 1) + rotl32(v2, 7) + rotl32(v3, 12) + rotl32(v4, 18)
	} else {
		h32 = seed + prime5
	}
	h32 += uint32(length)
	for p+4 <= length {
		h32 += uint32(binary.LittleEndian.Uint32(data[p:])) * prime3
		h32 = rotl32(h32, 17)
		h32 *= prime4
		p += 4
	}
	for p < length {
		h32 += uint32(data[p]) * prime5
		h32 = rotl32(h32, 11)
		h32 *= prime1
		p++
	}
	h32 ^= h32 >> 15
	h32 *= prime2
	h32 ^= h32 >> 13
	h32 *= prime3
	h32 ^= h32 >> 16
	return h32
}

func headerChecksum(data []byte) byte {
	h := xxh32(data, 0)
	return byte((h >> 8) & 0xFF)
}

func blockSizeFromCode(code int) int {
	switch code {
	case 4:
		return 64 * 1024
	case 5:
		return 256 * 1024
	case 6:
		return 1 * 1024 * 1024
	case 7:
		return 4 * 1024 * 1024
	default:
		return 4 * 1024 * 1024
	}
}

func parseBlockSize(s string) (int, bool) {
	if s == "" {
		return 0, false
	}
	orig := s
	s = strings.ToUpper(s)
	mult := 1
	if strings.HasSuffix(s, "KB") {
		mult = 1024
		s = strings.TrimSuffix(s, "KB")
	} else if strings.HasSuffix(s, "MB") {
		mult = 1024 * 1024
		s = strings.TrimSuffix(s, "MB")
	} else if strings.HasSuffix(s, "K") {
		mult = 1024
		s = strings.TrimSuffix(s, "K")
	} else if strings.HasSuffix(s, "M") {
		mult = 1024 * 1024
		s = strings.TrimSuffix(s, "M")
	} else if strings.HasSuffix(s, "B") {
		s = strings.TrimSuffix(s, "B")
	}
	val, err := strconv.Atoi(s)
	if err != nil {
		_ = orig
		return 0, false
	}
	return val * mult, true
}

func isTTY(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

